// WF-02: Detect Route (BMX-06 §6 / safety-net decision #10).
// nfm_reply stage guard (DR-1); NEW existing-user non-text branch; NEW_USER removed.
const input = $input.first().json;

const user = input.user || null;
const userStatus = user?.status || null;
const messageType = input.messageType || 'text';
const interactiveType = input.rawMessage?.interactive?.type || null;
const pendingUser = input.pendingUser || null;

let route;

// WhatsApp Flow form submission — valid ONLY pre-form (no user row yet, pending row present); else UNHANDLED.
if (messageType === 'interactive' && interactiveType === 'nfm_reply') {
  route = (user === null && pendingUser !== null) ? 'DETAILS_FORM' : 'UNHANDLED';

// "Payment Completed" button tap — only valid for payment_pending users
} else if (messageType === 'interactive' && interactiveType === 'button_reply' && user !== null && userStatus === 'payment_pending') {
  route = 'PAYMENT_CONFIRM';

// Post-consultation button tap (btn_feedback / btn_rebook) for consultation_closed users
} else if (messageType === 'interactive' && interactiveType === 'button_reply' && user !== null && userStatus === 'consultation_closed') {
  route = 'POST_CONSULT_TEXT';

// pendingUser exists (received form, not yet submitted) — free text
} else if (user === null && pendingUser !== null) {
  route = 'PRE_FORM_TEXT';

// Existing user sent a non-text/media message (NOT text, NOT interactive) — escalate + deflect.
} else if (user !== null && messageType !== 'text' && messageType !== 'interactive') {
  route = 'EXISTING_NON_TEXT';

// Existing-user text by status
} else if (user !== null && userStatus === 'payment_pending') {
  route = 'PAYMENT_PENDING_TEXT';
} else if (user !== null && userStatus === 'payment_submitted') {
  route = 'PAYMENT_SUBMITTED_TEXT';
} else if (user !== null && userStatus === 'consultation_active') {
  route = 'RELAY';
} else if (user !== null && userStatus === 'consultation_closed') {
  route = 'POST_CONSULT_TEXT';

} else {
  // Brand-new (user null + pendingUser null) no longer reaches WF-02 (WF-01 routes to WF-21 directly);
  // unmatched interactive (e.g. list_reply), unexpected status, blocked/opted_out leakage -> UNHANDLED.
  route = 'UNHANDLED';
}

return [{ json: { ...input, route } }];

const input = $input.first().json;
const phone = input.phoneNumber || '(unknown)';
const messageKind = input.messageType || 'unknown';
const interactiveType = input.rawMessage?.interactive?.type || null;
const userStatus = input.user?.status || 'not registered';
const onboardingInProgress = input.pendingUser ? 'yes' : 'no';
const content = (input.messageContent || '').slice(0, 200);

const lines = [
  `⚠️ The system couldn't route this message.`,
  `Phone: +${phone}`,
  `Message kind: ${messageKind}`,
];
if (interactiveType) lines.push(`Interactive type: ${interactiveType}`);
lines.push(`User status: ${userStatus}`);
lines.push(`Onboarding in progress: ${onboardingInProgress}`);
lines.push(`Content: ${content}`);
lines.push(`Please review.`);

return [{
  json: {
    channelId: 'C0A5B0ZE81E',
    messageText: lines.join('\n')
  }
}];

// WF-02 entry guard — design.md §2.1 + §2.7 + WF-02.pseudo Step 1.
// Accepts WF-01's full envelope incl. non-text/media (WF-01 no longer drops non-text).
const i = $('When Executed by Another Workflow').item.json;

if (!i.phoneNumber || typeof i.phoneNumber !== 'string')
  throw new Error('WF-02 contract: phoneNumber required (E.164 string), got: ' + JSON.stringify(i.phoneNumber));

// messageType: text | interactive | any known non-text/media type (image/audio/video/document/...).
// WF-00 sets messageType = raw WhatsApp message.type; any non-empty string is a valid transport type.
if (!i.messageType || typeof i.messageType !== 'string')
  throw new Error('WF-02 contract: messageType required (non-empty string), got: ' + JSON.stringify(i.messageType));

// messageContent key must be present (null allowed — media may carry no caption; WF-00 emits "[IMAGE]" etc.).
if (!('messageContent' in i))
  throw new Error('WF-02 contract: messageContent key required (string or null)');

// ── user object (null is valid — pre-form path) ──
if (i.user !== null && i.user !== undefined) {
  if (typeof i.user !== 'object' || Array.isArray(i.user))
    throw new Error('WF-02 contract: user must be null or an object, got: ' + typeof i.user);
  const u = i.user;
  if (u.id === undefined || u.id === null)
    throw new Error('WF-02 contract: user.id required (integer)');
  if (!u.phone_number || typeof u.phone_number !== 'string')
    throw new Error('WF-02 contract: user.phone_number required (E.164 string)');
  if (u.name === undefined || u.name === null)
    throw new Error('WF-02 contract: user.name required (string)');
  const validStatuses = ['payment_pending', 'payment_submitted', 'consultation_active', 'consultation_closed', 'blocked', 'opted_out'];
  if (!u.status || !validStatuses.includes(u.status))
    throw new Error('WF-02 contract: user.status must be a valid state-machine value, got: ' + JSON.stringify(u.status));
  if (!('slack_channel_id' in u))
    throw new Error('WF-02 contract: user.slack_channel_id key required (string or null)');
  if (!('current_consultation_id' in u))
    throw new Error('WF-02 contract: user.current_consultation_id key required (integer or null)');
} else if (i.user === undefined) {
  throw new Error('WF-02 contract: user key required (object or null), got: undefined');
}

// ── pendingUser (null valid) ──
if (i.pendingUser !== null && i.pendingUser !== undefined) {
  if (typeof i.pendingUser !== 'object' || Array.isArray(i.pendingUser))
    throw new Error('WF-02 contract: pendingUser must be null or an object, got: ' + typeof i.pendingUser);
} else if (i.pendingUser === undefined) {
  throw new Error('WF-02 contract: pendingUser key required (object or null), got: undefined');
}

return [{ json: i }];

// WF-02: Normalize Template-Button Tap (PDF-17 / PDF-19).
// POST-FILTER — runs only after WF-01's country / blocked / opted-out gates, so it never
// processes red-flagged-country or blocked traffic. A tap on a *template* quick-reply button
// arrives from WF-00 as messageType='button' with rawMessage.button.{text,payload} — a DIFFERENT
// shape (M5) than an interactive button_reply. Convert the button label to our internal action id
// and reshape the payload into the interactive button_reply form, so Detect Route and every
// downstream handler work UNCHANGED. Non-button messages pass through untouched.

const i = $input.first().json;

// Approved template button label -> internal action id (the ids downstream already routes on).
const BUTTON_MAP = {
  'Payment Completed': 'payment_completed',   // payment_rejection template (PDF-17)
  'Leave Feedback': 'btn_feedback',           // consultation_closed template (PDF-19)
  'Book Again': 'btn_rebook',                 // consultation_closed template (PDF-19)
  'Done, Thanks.': 'btn_done'                 // consultation_closed template (PDF-19)
};

const raw = i.rawMessage || null;
const isTemplateButtonTap = i.messageType === 'button' && raw && raw.type === 'button' && raw.button;

if (!isTemplateButtonTap) {
  return [{ json: i }];   // pass through unchanged
}

const label = String(raw.button.text || raw.button.payload || '').trim();
// Fall back to the raw payload/label if the label is not in the map, so an unexpected template
// button still routes by user status like any other button_reply rather than mis-routing as media.
const actionId = BUTTON_MAP[label] || raw.button.payload || label;

const normalizedRaw = Object.assign({}, raw, {
  interactive: { type: 'button_reply', button_reply: { id: actionId, title: raw.button.text || label } }
});

return [{ json: Object.assign({}, i, {
  messageType: 'interactive',
  messageContent: actionId,
  messageContentUpper: String(actionId).toUpperCase().trim(),
  interactiveLabel: raw.button.text || label,
  rawMessage: normalizedRaw
}) }];

